#include "prefix_cipher_test_fixture.hpp"
using namespace cipher_test;
namespace {
void vectors(){
    const auto plain=unhex("6bc1bee22e409f96e93d7e117393172aae2d8a571e03ac9c9eb76fac45af8e5130c81c46a35ce411e5fbc1191a0a52eff69f2445df4f9b17ad2b417be66c3710");
    const auto ecb=unhex("3ad77bb40d7a3660a89ecaf32466ef97f5d3d58503b9699de785895a96fdbaaf43b1cd7f598ece23881b00e3ed0306887b0c785e27e8ad3f8223207104725dd4");
    const auto cbc=unhex("7649abac8119b246cee98e9b12e9197d5086cb9b507219ee95db113a917678b273bed6b8e3c1743b7116e69e222295163ff1caa1681fac09120eca307586e1a7");
    for(unsigned mode:{1U,2U}){Fixture f;f.state.mode_00=mode;f.seed(plain);check(f.encrypt()&&f.text().substr(0,64)==(mode==1?cbc:ecb)&&f.f.value.size_10==80,"existing known-answer four-block ECB/CBC prefix and extra padding block");auto expected_iv=test_iv;if(mode==1)std::copy_n(reinterpret_cast<const std::uint8_t*>(f.text().data()+64),16,expected_iv.begin());check(f.state.iv_b4==expected_iv,"typed IV final ciphertext only for CBC");const auto ciphertext=f.text();Fixture d;d.state.mode_00=mode;d.seed(ciphertext);check(d.decrypt()&&d.text()==plain&&d.state.iv_b4==expected_iv,"native prefix wrappers and real AES/CBC lower sources decrypt known-answer payload");}
}
void ordinary(){
    std::vector<unsigned> lengths;for(unsigned i=0;i<=64;++i)lengths.push_back(i);for(auto i:{128U,2047U,4095U,8192U})lengths.push_back(i);
    for(unsigned mode:{1U,2U})for(unsigned prefix:{0U,1U,65U})for(bool spare:{false,true})for(auto n:lengths){
        std::string input(prefix,'P');for(unsigned i=0;i<n;++i)input.push_back(static_cast<char>((i*71+n)&255));
        c::Cipher oracle;if(mode==1)oracle.set_key_and_iv_042760(test_key,test_iv);else oracle.set_key_042780(test_key);auto expected=input;check(oracle.encrypt_with_offset(expected,prefix),"existing semantic AES reference accepts ordinary domain");
        Fixture f;f.state.mode_00=mode;f.seed(input,spare?input.size()+32:15);const auto capacity=f.f.value.capacity_18;
        check(f.encrypt(prefix)&&f.text()==expected&&f.text().substr(0,prefix)==input.substr(0,prefix),"complete binary ciphertext/prefix oracle across inline/heap/spare/growth/offset boundaries");
        check(f.f.memory.view(s::receive_buffer_address(f.f.value)+f.f.value.size_10,1)[0]==0&&f.f.value.size_10==input.size()+16-((input.size()-prefix)&15),"padding length and storage terminator exact");
        check(f.state.iv_b4==(mode==1?oracle.iv():test_iv)&&f.schedule.iv()==c::Key{},"same mutable typed IV chain; existing block-only schedule IV untouched");
        if(spare)check(f.f.value.capacity_18==capacity&&f.f.api.allocations.empty(),"spare path does not reallocate");
        Fixture d;d.state.mode_00=mode;d.seed(expected);check(d.decrypt(prefix)&&d.text()==input&&d.state.iv_b4==f.state.iv_b4,"prefix decrypt/unpad full payload and IV oracle");
    }
    for(unsigned mode:{1U,2U}){Fixture e,d;e.state.mode_00=d.state.mode_00=mode;c::Cipher oracle;if(mode==1)oracle.set_key_and_iv_042760(test_key,test_iv);else oracle.set_key_042780(test_key);for(auto input:{std::string("first"),std::string(16,'Z'),std::string("last\0message",12)}){e.seed(input);auto expected=input;oracle.encrypt_042610(expected);check(e.encrypt()&&e.text()==expected,"multiple calls retain coherent cipher chain including padding blocks");d.seed(e.text());check(d.decrypt()&&d.text()==input&&d.state.iv_b4==e.state.iv_b4,"paired multi-call CBC/ECB state remains aligned");}}
}
void padding(){
    for(unsigned pad=0;pad<256;++pad){std::string plain(16,'Q');plain.back()=static_cast<char>(pad);Fixture f;f.seed(raw_encrypt(plain));const auto result=f.decrypt();check(result==(pad==1)&&f.text()==(pad==1?plain.substr(0,15):plain),"all signed padding bytes; failed validation retains decrypted payload and size");}
    for(unsigned pad=1;pad<=16;++pad){std::string plain(16,'Q');std::fill(plain.end()-pad,plain.end(),static_cast<char>(pad));Fixture f;f.seed(raw_encrypt(plain));check(f.decrypt()&&f.text()==plain.substr(0,16-pad),"every valid padding length");for(unsigned i=0;i+1<pad;++i){auto bad=plain;bad[16-pad+i]^=1;Fixture d;d.seed(raw_encrypt(bad));check(!d.decrypt()&&d.text()==bad,"each wrong padding position returns false without rollback");}}
    {Fixture f;f.state.mode_00=1;c::Cipher oracle;oracle.set_key_and_iv_042760(test_key,test_iv);auto plain=std::string(32,'Q');auto encrypted=plain;oracle.encrypt_042610(encrypted);encrypted.resize(32);f.seed(encrypted);check(!f.decrypt()&&f.text()==plain&&std::equal(f.state.iv_b4.begin(),f.state.iv_b4.end(),reinterpret_cast<const std::uint8_t*>(encrypted.data()+16)),"CBC invalid padding still leaves plaintext and last original ciphertext IV");}
}
void live_and_boundaries(){
    for(unsigned mode:{0U,3U}){Fixture f;f.state.mode_00=mode;f.seed("abcdef",31);const auto before=f.f.value;check(!f.decrypt()&&f.f.value.storage_00==before.storage_00&&f.f.value.size_10==6&&f.blocks.calls.empty(),"unkeyed/unknown decrypt no mutation");const auto result=f.encrypt();check(!result&&f.f.value.size_10==(mode?16U:6U)&&f.blocks.calls.empty(),"unknown encryption mode pads before false; mode0 returns before touching prefix");}
    {Fixture f;f.state.mode_00=0;f.f.value.capacity_18=UINT64_MAX;f.f.value.size_10=UINT64_MAX;f.f.regions.fill({});check(!f.encrypt()&&!f.decrypt(),"mode0 does not dereference invalid string fields or memory");}
    for(unsigned n=1;n<48;++n)if(n%16){Fixture f;f.seed(std::string(n,'X'));auto before=f.text();check(!f.decrypt()&&f.text()==before&&f.blocks.calls.empty(),"unaligned decrypt rejects before block provider");}
    {Fixture f;f.seed("prefix"+std::string(1,1));check(f.decrypt(23)&&f.text()=="prefix"&&f.blocks.calls.empty(),"offset beyond size with aligned unsigned extent can skip ECB and unpad full string; no invented offset guard");}
    {Fixture f;f.seed("abc");check(f.encrypt(32)&&f.f.value.size_10==16&&f.blocks.calls.empty(),"ECB offset beyond padded size returns true after padding without blocks");}
    {Fixture f;f.seed(std::string(16,'Q')+std::string(16,1));f.blocks.noop=true;f.blocks.after=[&](const auto&){f.state.mode_00=0;};check(f.decrypt()&&f.blocks.calls.size()==2&&f.f.value.size_10==31,"decrypt mode cached across lower callbacks while live size drives block loop");}
    {Fixture f;f.seed(std::string(31,'Q'),63);f.blocks.noop=true;f.blocks.after=[&](const auto&){f.state.mode_00=0;};check(f.encrypt()&&f.blocks.calls.size()==2&&f.f.value.size_10==32,"encrypt mode selected after resize remains cached across block calls");}
    {Fixture f;f.seed(std::string(31,'Q'),63);f.effects.after_fill=[&](){f.state.mode_00=0;};check(!f.encrypt()&&f.f.value.size_10==32&&f.blocks.calls.empty(),"mode reloaded after fill mutation, padded data remains on false");}
    {Fixture f;f.seed("abc",31);f.effects.after_fill=[&](){f.state.mode_00=1;f.f.value.size_10=1;};f.blocks.noop=true;check(f.encrypt()&&f.blocks.calls.size()==1&&f.blocks.calls[0].kind=="cbc-enc"&&f.blocks.calls[0].count==1&&f.f.value.size_10==1,"CBC uses live post-fill size/mode, not cached padded extent");}
    {Fixture f;f.seed(std::string(32,1),32);auto& other=f.f.add(32);std::fill(other.bytes.begin(),other.bytes.end(),1);f.blocks.noop=true;f.blocks.after=[&](const auto&){b::word(f.f.value.storage_00,other.raw);f.f.value.size_10=16;};check(f.decrypt()&&f.blocks.calls.size()==1&&s::receive_buffer_address(f.f.value)==other.raw&&f.f.value.size_10==15,"ECB callback pointer/size change controls final padding source and next loop bound");}
    {Fixture f;f.state.mode_00=3;f.seed(std::string(15,'Q'));f.f.value.size_10=UINT64_MAX;check(!f.encrypt(UINT64_MAX)&&f.f.value.size_10==15&&f.f.value.storage_00[15]==0&&f.effects.fills==0,"symbolic padding-size wrap follows native shrink/NUL path before unknown-mode false");}
    {Fixture f;f.seed("");rejects<s::UnsupportedInput>([&]{f.decrypt();});check(!f.f.value.size_10&&f.blocks.calls.empty(),"empty ECB follows native pre-base padding read into explicit bounded failure");}
    {Fixture f;f.seed("");std::array<std::uint8_t,1> preceding{1};const auto base=s::receive_buffer_address(f.f.value);f.f.regions[31]={base-1,preceding};try{f.decrypt();throw std::runtime_error("expected length terminal");}catch(const b::Terminal& e){check(e.kind==1&&f.f.api.allocations.empty(),"mapped pre-base padding1 causes unsigned resize growth length terminal; no empty guard");}}
}
void failures_and_cbc(){
    for(bool after:{false,true}){Fixture f;f.seed(std::string(31,'Q'),63);auto fail=[](){throw Failure{9};};if(after)f.effects.after_fill=fail;else f.effects.before_fill=fail;rejects<Failure>([&]{f.encrypt();});const auto data=s::receive_buffer_address(f.f.value);check(f.f.value.size_10==32&&f.f.memory.view(data+31,1)[0]==(after?1:0)&&f.f.memory.view(data+32,1)[0]==0xcc&&f.blocks.calls.empty(),"fill failure exposes padded metadata; before/after bytes differ, final NUL/blocks absent");}
    for(bool large:{false,true}){Fixture f;f.seed(std::string(large?4095:15,'Q'));const auto before=f.f.value;f.f.api.null_allocate=true;try{f.encrypt();throw std::runtime_error("expected allocation failure");}catch(const b::Terminal& e){check(large&&e.kind==3&&f.f.value.size_10==before.size_10&&f.blocks.calls.empty(),"large NULL rejected before padding metadata");}catch(const s::UnsupportedInput&){check(!large&&f.f.value.size_10==16&&f.f.value.capacity_18==31&&f.blocks.calls.empty(),"small NULL padding growth retains new metadata/old prefix before bounded COPY");}}
    {Fixture f;f.seed(std::string(31,'Q'),63);f.blocks.after=[](const auto&){throw Failure{9};};rejects<Failure>([&]{f.encrypt();});check(f.f.value.size_10==32&&f.blocks.calls.size()==1,"block exception retains padding and first encrypted block");}
    for(bool encrypt:{false,true}){Fixture f;f.seed(std::string(16,'Q'),31);const auto address=s::receive_buffer_address(f.f.value);auto& region=f.f.regions[1];region.bytes=region.bytes.first(16);const auto original=f.f.memory.view(address,16);c::Key first;std::copy(original.begin(),original.end(),first.begin());rejects<s::UnsupportedInput>([&]{if(encrypt)f.blocks.real.encrypt_cbc_045580(f.state,address,17);else f.blocks.real.decrypt_cbc_0454e0(f.state,address,17);});check(f.state.iv_b4==(encrypt?test_iv:first),"CBC partial-batch failure: encrypt IV unchanged until final store; decrypt IV updates after each block");}
    {Fixture f;const auto before=f.state.iv_b4;f.blocks.real.decrypt_cbc_0454e0(f.state,0,0);f.blocks.real.encrypt_cbc_045580(f.state,0,0);check(f.state.iv_b4==before,"CBC count0 performs no input access; encryption self-copies current IV");}
}
}
int main(){try{vectors();ordinary();padding();live_and_boundaries();failures_and_cbc();std::cout<<"PASS: "<<checks<<" socket prefix cipher checks; actual042480/042610 and045620/045630/0454e0/045580 sources, known-answer AES, binary offset/padding/IV oracle, live callbacks and bounded failure prefixes\n";}catch(const std::exception& e){std::cerr<<"FAIL after "<<checks<<" checks: "<<e.what()<<'\n';return 1;}catch(...){std::cerr<<"FAIL: unexpected terminal\n";return 1;}}
